'use strict';
colors.Fennel='#6fae8c';
bondDescriptions.Fennel='Level 2: +1 wild herb per pick';
creatureTemperaments.Fennel={trait:'Playful · loves the shallows',clues:['It splashes at the water’s edge, watching for a reaction.','It paddles closer, blowing tiny ripples your way.'],actions:[['splash','Splash back'],['still','Sit quietly'],['hum','Hum a low tune']],best:['splash','hum'],good:'It paddles a happy circle around you.',bad:'It ducks under a lily pad. Try matching its energy.'};
const marshTypes=['marshMarker','marshNest'];
const marshNear=nearest;nearest=function(){let best=marshNear(),d=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>marshTypes.includes(o.type))){const n=Math.hypot(o.x-player.x,o.y-player.y);if(n<d){best=o;d=n;}}return best;};
function marshChapter(){return MarshCore.chapters[state.marsh.stage];}
function marshQuestCard(){const q=state.marsh,c=marshChapter();return `<article class="story-feature">${gameIcon(q.stage===6?'check':'fish')}<small>FERNWATER MARSH · ${Math.min(6,q.stage+1)} / 6</small><h3>${c?c[0]:'A marsh alive with reeds and wings'}</h3><p>${c?c[1]:'Fennel has a home, the boardwalk holds firm and the coast road is open.'}</p>${q.stage===1?`<span>${q.markers.length} / 3 sunken posts found</span>`:q.stage===2?`<span>${Math.min(12,Math.max(0,state.frontier.gathered.herbs-q.herbStart))} / 12 fresh herbs</span>`:''}</article>`;}
function marshGuide(){panel('The marsh opens up',marshQuestCard()+'<div class="actions"><button data-ui="close">Back to the trail</button><button data-front="requests">Regional requests</button></div>','Iris’s survey','marsh');}
function irisDialog(){const q=state.marsh;const lines=['“The reeds have swallowed our old boardwalk. Will you help me bring the route back?”','“Three posts once marked the crossing. Find them beneath the reeds and I’ll know where to rebuild.”','“Fresh herbs tell me the water’s healthy again. Pick twelve, then come find me.”','“Forty timber and twelve herbs should mend the crossing. Meet me at the boardwalk.”','“Something’s been paddling in the shallows. Follow the reed trail west and see if it will come out.”','“You found our little wanderer! Let’s get this crossing open again.”','“Listen to the water move freely again. You’ve opened the whole marsh.”'];const action=q.stage===0?'talk':q.stage===2?'herb':q.stage===5?'finish':null;panel('Iris',`<p>${lines[q.stage]}</p>${marshQuestCard()}<div class="actions">${action?`<button data-marsh="${action}" ${q.stage===2&&state.frontier.gathered.herbs-q.herbStart<12?'disabled':''}>${q.stage===0?'I’ll help':q.stage===2?'Show the fresh herbs':'Celebrate · collect rewards'}</button>`:''}<button data-front="requests">Requests</button><button data-ui="close">See you soon</button></div>`,'Wetland keeper','marsh');}
function marshObjectMenu(o){const q=state.marsh;let title='The marsh',body='',action='';
 if(o.type==='marshMarker'){title='A sunken boardwalk post';body=q.markers.includes(o.marker)?'Already logged in Iris’s notes.':'A weathered post, half sunk in the reeds. Worth reporting back.';if(q.stage===1&&!q.markers.includes(o.marker))action=`<button data-marsh="marker" data-marker="${o.marker}">Log this post</button>`;}
 if(o.type==='landmark'){title='The old boardwalk crossing';body=q.stage<3?'Iris has a plan for this place. Visit the camp to the west.':q.stage===3?'Repair the crossing with fresh timber and herbs.':q.stage<6?'The frame is repaired. Follow Iris’s plan to bring the boardwalk back.':'A steady crossing. Herb gathering here now yields an extra sprig.';if(q.stage===3)action=`${state.frontier.projects.boardwalk?'<p>Materials already paid for.</p>':`<div class="ingredient-row">${chip('wood',40,state.wood)}${chip('herbs',12,state.herbs)}</div>`}<button data-marsh="repair" ${!state.frontier.projects.boardwalk&&(state.wood<40||state.herbs<12)?'disabled':''}>Repair the crossing</button>`;}
 if(o.type==='marshNest'){if(q.stage>=4&&!state.team.includes('Fennel')){encounter={name:'Fennel',trust:0};encounterDialog();return;}title='The quiet shallows';body=state.team.includes('Fennel')?'Fennel rests in a sun-warmed pool between the reeds. Always close, always curious.':'Tiny ripples circle a patch of still water. Perhaps an open crossing will bring its owner out.';}
 panel(title,`<p>${body}</p>${action}<div class="actions"><button data-marsh="guide">Iris’s plan</button><button data-ui="close">Keep exploring</button></div>`,'Fernwater Marsh','marsh');
}
const marshInteract=interact;interact=function(){if(!dialog&&!activity){const o=nearest();if(SaveStore.status().blocked){saveMenu();return;}if(map.id==='marsh'&&o?.name==='Iris'){irisDialog();return;}if(map.id==='marsh'&&(marshTypes.includes(o?.type)||o?.type==='landmark')){faceTarget(o);marshObjectMenu(o);return;}}marshInteract();};
app.addEventListener('click',e=>{const b=e.target.closest('[data-marsh]');if(!b||b.disabled)return;const a=b.dataset.marsh;if(a==='guide'){marshGuide();return;}if(SaveStore.status().blocked){saveMenu();return;}const o=nearest(),allowed=['talk','herb','finish'].includes(a)?map.id==='marsh'&&o?.name==='Iris':map.id==='marsh'&&({marker:'marshMarker',repair:'landmark'}[a]===o?.type);if(!allowed||(a==='marker'&&Number(b.dataset.marker)!==o.marker))return;if(MarshCore.act(state,a,Number(b.dataset.marker))){finish(a==='finish'?'The marsh opens up! +100 coins · +3 trail marks · +6 herbs':a==='marker'?`${state.marsh.markers.length} / 3 posts found`:a==='repair'?'Boardwalk repaired! Something is still paddling in the shallows.':'Iris’s plan updated.');}if(o?.name==='Iris')irisDialog();else marshObjectMenu(o);});
const marshTick=tickActivities;tickActivities=function(dt){const people=map.npcs;if(map.id==='tessa')map.npcs=[];marshTick(dt);if(map.id==='tessa')map.npcs=people;if(MarshCore.act(state,'friend')){state.jobs.Fennel='fish';finish('Fennel joined the marsh camp. Tell Iris the good news!');}};
const marshComplete=completeActivity;completeActivity=function(){if(activity?.o.type==='herb'&&state.life.active==='Fennel'&&MossSystems.level(state,'Fennel')>=2)state.herbs++;marshComplete();};
const marshAdventure=adventureMenu;adventureMenu=function(){marshAdventure();if(taskTab==='story'){const b=document.createElement('button');b.dataset.marsh='guide';b.textContent=state.marsh.stage===6?'Fernwater Marsh · Complete':'Iris’s marsh · '+marshChapter()[0];document.querySelector('.dialog .panel-tabs').after(b);}};
const marshMap=mapPanel;mapPanel=function(){marshMap();const b=document.createElement('button');b.dataset.marsh='guide';b.textContent='Fernwater Marsh · Iris’s plan';document.querySelector('.dialog').append(b);};
const marshObject=object;object=function(o){if(map.id==='marsh'){if(o.type==='marshMarker'){const found=state.marsh.markers.includes(o.marker);rr(o.x-3,o.y-14,6,14,'#5c6b48');rr(o.x-7,o.y-17,14,6,found?'#c7b26a':'#8f7a4f');text(found?'✓':'?',o.x,o.y-12,found?'#eef3c0':'#f6e6ac',9);return;}if(o.type==='marshNest'){rr(o.x-13,o.y-3,26,7,'#4c6b63');rr(o.x-9,o.y-6,18,5,'#79a596');if(state.marsh.stage>=4&&!state.team.includes('Fennel'))text('?',o.x,o.y-10,'#fff0b8',12);return;}}marshObject(o);};
// Old saves may stand where the new markers or nest now block a path.
if(map.id==='marsh'&&blocked(map,player.x,player.y)){player.x=45*T+16;player.y=19*T+16;follower.x=player.x-24;follower.y=player.y;save();}
